  ('car-audi-r8', 'Audi R8 V10 Performance', 'Audi', 'R8 V10 Performance Coupe', 2024, 'Sports', 800000, 150000, 612, 3.1, 331, 'Automatic', 'Petrol', 2, 2, 'Crimson Red Metallic', '/images/car_red_sportscar_1794399930525.jpg', array['/images/car_red_sportscar_1794399930525.jpg', '/images/car_hero_banner_1794399931970.jpg', '/images/car_grey_sports_coupe_1794399933041.jpg']::text[], 'Experience pure naturally aspirated motorsport adrenaline. The Audi R8 V10 Performance Coupe features legendary Quattro all-wheel drive, ceramic braking system, and a spine-tingling 5.2-liter V10 engine delivering unmatched track-tuned precision.', array['Quattro All-Wheel Drive', 'Ceramic Carbon Brakes', 'Bang & Olufsen 3D Sound', 'Virtual Cockpit Display', 'Sport Exhaust System', 'Apple CarPlay & Android Auto', 'Adaptive Magnetic Ride', 'Heated Nappa Leather Seats']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Victoria Island, Lagos', '250 miles / day', 'Aurevon Services Fleet', 4.98, 4.95, 142, true, true, true),
  ('car-range-rover', 'Range Rover Autobiography', 'Land Rover', 'Autobiography LWB V8', 2024, 'SUV', 800000, 180000, 523, 4.4, 261, 'Automatic', 'Hybrid', 5, 4, 'Obsidian Black Metallic', '/images/car_black_luxury_suv_1794399931535.jpg', array['/images/car_black_luxury_suv_1794399931535.jpg', '/images/car_hero_banner_1794399931970.jpg']::text[], 'The pinnacle of refined British luxury and commanding off-road poise. The Long Wheelbase Autobiography offers executive airline rear seating with hot stone massage, Meridian Signature audio, and whisper-quiet acoustic cabin insulation.', array['Electronic Air Suspension', 'Executive Rear Class Seating', 'Meridian 35-Speaker Sound', 'Panoramic Sliding Roof', 'Heated & Cooled Seats with Massage', '360-Degree 3D Surround Camera', 'Soft-Close Luxury Doors', 'Cabin Air Purification Plus']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '300 miles / day', 'Aurevon Services Fleet', 4.98, 4.92, 98, true, true, true),
  ('car-bmw-m4', 'BMW M4 Competition', 'BMW M', 'Competition xDrive Coupe', 2024, 'Sports', 800000, 200000, 503, 3.4, 290, 'Automatic', 'Petrol', 4, 2, 'Dravit Grey Metallic', '/images/car_grey_sports_coupe_1794399933041.jpg', array['/images/car_grey_sports_coupe_1794399933041.jpg', '/images/car_red_sportscar_1794399930525.jpg', '/images/car_black_luxury_suv_1794399931535.jpg']::text[], 'Bavarian engineering pushed to the absolute edge. TwinPower Turbo inline-six engine with rear-biased xDrive intelligent traction, M Carbon bucket seats, and razor-sharp steering dynamics crafted for the open road.', array['M xDrive Intelligent All-Wheel', 'M Carbon Bucket Seats', 'Harman Kardon Surround Sound', 'M Carbon Exterior Package', 'BMW Curved Display with OS 8.5', 'Head-Up Display with Track Mode', 'Active M Differential', 'Adaptive M Suspension']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '200 miles / day', 'Bavarian Sport Rentals', 4.93, 4.89, 115, true, false, true),
  ('car-g63-amg', 'Mercedes-AMG G63', 'Mercedes-Benz', 'G63 AMG Biturbo V8', 2024, 'Luxury', 800000, 200000, 577, 4.2, 240, 'Automatic', 'Petrol', 5, 4, 'Night Black Magno', '/images/car_black_luxury_suv_1794399931535.jpg', array['/images/car_black_luxury_suv_1794399931535.jpg', '/images/car_red_sportscar_1794399930525.jpg', '/images/car_hero_banner_1794399931970.jpg']::text[], 'An iconic silhouette that commands attention wherever it rolls. Handcrafted 4.0-liter V8 biturbo engine producing 577 horsepower, signature dual side-exit exhaust roar, and bespoke diamond-quilted designo interior.', array['Handcrafted AMG 4.0L V8 Biturbo', 'AMG Performance Exhaust System', 'Three 100% Differential Locks', 'Burmester Surround Sound', 'AMG Ride Control Suspension', 'Exclusive Nappa Leather Interior', 'Carbon Fiber Trim Elements', 'Multibeam LED Headlights']::text[], array['Minimum driver age 25', 'Valid driving licence required at pick-up', 'No smoking or pets', 'Return with the same fuel or charge level']::text[], 'Calabar, Cross River State', '200 miles / day', 'Aurevon Services Fleet', 4.98, 4.97, 164, true, true, true)
